using System.Text.Json;

namespace GreyHaven.Reports;

/// <summary>
/// The walkthrough pictures (assets/illustrations, generated by tools/illustrations/build.py):
/// simplified drawings of the real screens in the Market Day style, with alt text.
/// </summary>
public static class Illustrations
{
    private sealed record Entry(string Alt, string CheckedAgainst);

    private static readonly Lazy<IReadOnlyDictionary<string, Entry>> Catalog = new(() =>
    {
        using var stream = typeof(Illustrations).Assembly.GetManifestResourceStream("Illustrations.catalog.json");
        if (stream is null) return new Dictionary<string, Entry>();
        return JsonSerializer.Deserialize<Dictionary<string, Entry>>(stream, new JsonSerializerOptions { PropertyNameCaseInsensitive = true }) ?? [];
    });

    public static IReadOnlyCollection<string> Ids => Catalog.Value.Keys.ToList();

    public static bool Exists(string? id) => id is not null && Catalog.Value.ContainsKey(id);

    /// <summary>Alt text: what the picture shows, for screen readers.</summary>
    public static string? Alt(string? id) => id is not null && Catalog.Value.TryGetValue(id, out var e) ? e.Alt : null;

    /// <summary>The picture as SVG markup (light and dark colours built in), or null.</summary>
    public static string? Svg(string? id)
    {
        if (!Exists(id)) return null;
        using var stream = typeof(Illustrations).Assembly.GetManifestResourceStream($"Illustrations.{id}.svg");
        if (stream is null) return null;
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    /// <summary>The keyboard picture for a startup menu key, e.g. "F12" or "Esc, then F9".</summary>
    public static string BootKeyId(string key)
    {
        if (key.Contains("volume", StringComparison.OrdinalIgnoreCase)) return "boot-key-surface";
        var slug = string.Join("-", key.ToLowerInvariant().Split([' ', ',', '.'], StringSplitOptions.RemoveEmptyEntries).Where(w => w != "then"));
        return $"boot-key-{slug}";
    }
}
